from functools import partialmethod
from pathlib import Path
Path.read_text = partialmethod(Path.read_text, encoding='utf-8')
Path.write_text = partialmethod(Path.write_text, encoding='utf-8')
p=Path('src/lib/editorial.ts');p.write_text('''import { z } from "zod";
const text = z.string().max(3000);
export const projectSchema = z.object({
  title: text, problem: text, contribution: text, platforms: text, approach: text, outcomes: text,
  attribution: z.enum(["individual", "identiverse"]), source: text,
  approval: z.enum(["draft", "approved"]), published: z.boolean(), order: z.number()
}).refine(p => !p.published || (p.approval === "approved" && [p.problem,p.contribution,p.platforms,p.approach,p.outcomes,p.source].every(v => v.trim())), "Published experience requires approval, source material and all evidence fields");
export const editorialSchema = z.object({
  projects: z.array(projectSchema).max(30).default([]),
  profiles: z.array(z.object({ name: text, role: text, bio: text, credentials: text, published: z.boolean(), order: z.number() })).max(20).default([]),
  testimonials: z.array(z.object({ quote: text, attribution: text, approved: z.boolean(), published: z.boolean(), order: z.number() }).refine(t => !t.published || (t.approved && !!t.attribution.trim() && !!t.quote.trim()), "Testimonials require moderation and attribution")).max(30).default([]),
  faqs: z.array(z.object({ q: text, a: text, published: z.boolean(), order: z.number() })).max(30).default([]),
  legalName: text.default(""), businessDetails: text.default(""), workingOverlap: text.default(""),
  schedulingUrl: z.union([z.url().startsWith("https://"), z.literal("")]).default(""), responseExpectation: text.default("")
});
export type Editorial = z.infer<typeof editorialSchema>;
export const defaultEditorial: Editorial = {
  projects: ["Okta–Google Workspace domain migration", "IBM Verify Access custom authentication / federation", "Keycloak custom-authenticator integration"].map((title, order) => ({ title, problem: "", contribution: "", platforms: "", approach: "", outcomes: "", attribution: "individual", source: "", approval: "draft", published: false, order })),
  profiles: [], testimonials: [], faqs: [], legalName: "", businessDetails: "", workingOverlap: "", schedulingUrl: "", responseExpectation: ""
};
export function publishedProjects(editorial: Editorial) { return editorial.projects.filter(p => p.published && p.approval === "approved" && [p.source,p.problem,p.contribution,p.platforms,p.approach,p.outcomes].every(v => v.trim())).sort((a,b) => a.order-b.order); }
''')
